        "whyImportant": "羽柴秀吉（のちの豊臣秀吉）から豊臣秀吉へ名を変えながら天下人となり、検地・刀狩で近世の支配を整えた一方、朝鮮出兵は東アジアに大きな被害をため、日本史の流れと後世への影響を理解するうえで重要です。"
